15	// As of Cutlass v3.6.0, if size(ClusterShape) == 1, PipelineTmaAsync has all threads
16	// signaling the barrier during consumer_release. This causes a perf regression in FA3
17	// forward pass (especially hdim 128 causal). We instead reimplement the version of
18	// PipelineTmaAsync before v3.6.0 where only 1 out of 128 threads signals the barrier.
19	//
20	// Assumption: params.num_consumers % NumThreadsPerWarpGroup == 0
21	template <int Stages_, class Base=cutlass::PipelineTmaAsync<Stages_>>
22	class PipelineTmaAsyncNoCluster: public Base {
23	public:
24	  using FullBarrier = typename Base::FullBarrier;
25	  using EmptyBarrier = typename Base::EmptyBarrier;
26	  static constexpr uint32_t Stages = Stages_;
27	  using PipelineState = typename Base::PipelineState;
28	
29	  using SharedStorage = typename Base::SharedStorage;
30	  using ThreadCategory = typename Base::ThreadCategory;
31	  using Params = typename Base::Params;
32	
33	  static
34	  CUTLASS_DEVICE
35	  void
36	  init_barriers(SharedStorage& storage, Params params) {
37	    int warp_idx = canonical_warp_idx_sync();
38	    bool is_initializing_warp = (warp_idx == 0);
39	    if (is_initializing_warp) {
40	      // Barrier FULL and EMPTY init
41	      constexpr int producer_arv_cnt = 1;
42	      uint32_t const num_consumer_warpgroups_per_cluster = (params.num_consumers + NumThreadsPerWarpGroup - 1) / NumThreadsPerWarpGroup;
43	      uint32_t const multicast_consumer_arrival_count = num_consumer_warpgroups_per_cluster;
44	
45	      cutlass::arch::detail::initialize_barrier_array_pair_aligned<decltype(storage.full_barrier_), decltype(storage.empty_barrier_), Stages>(
46	          storage.full_barrier_, storage.empty_barrier_, producer_arv_cnt, multicast_consumer_arrival_count);
47	    }
48	    cutlass::arch::fence_barrier_init();
49	  }
50	
51	  template<class ClusterShape, class InitBarriers, class InitMasks>
52	  CUTLASS_DEVICE
53	  PipelineTmaAsyncNoCluster(SharedStorage& storage, Params params, ClusterShape cluster_shape, InitBarriers = {}, InitMasks = {})
54	      : Base(storage, params, make_shape(_1{}, _1{}, _1{}) /*cluster_shape*/, cute::false_type{} /*init_barriers*/, cute::false_type{} /*init_masks*/)
55	      , empty_barrier_ptr_(&storage.empty_barrier_[0]) {
56	
57	    int warp_idx = canonical_warp_idx_sync();
58	    int lane_predicate = cute::elect_one_sync();
59	
60	    static_assert(cute::is_same_v<InitBarriers, cute::true_type> || cute::is_same_v<InitBarriers, cute::false_type>);
61	    static_assert(cute::is_same_v<InitMasks, cute::true_type> || cute::is_same_v<InitMasks, cute::false_type>);
62	    if constexpr (cute::is_same_v<InitBarriers, cute::true_type>) {
63	      init_barriers(storage, params);
64	    }
65	
66	  }
67	
68	  // Constructor
69	  template<class ClusterShape>
70	  CUTLASS_DEVICE
71	  PipelineTmaAsyncNoCluster(SharedStorage& storage, Params params, ClusterShape cluster_shape)
72	      : PipelineTmaAsyncNoCluster(storage, params, cluster_shape, cute::true_type{}, cute::true_type{}) { }
73	
74	  template<class ClusterShape, class InitBarriers>
75	  CUTLASS_DEVICE
76	  PipelineTmaAsyncNoCluster(SharedStorage& storage, Params params, ClusterShape cluster_shape, InitBarriers = {})
77	      : PipelineTmaAsyncNoCluster(storage, params, cluster_shape, InitBarriers{}, cute::true_type{}) { }
78	
79	  CUTLASS_DEVICE
80	  void consumer_release(PipelineState state) {
81	    consumer_release(state.index());
82	  }
83	
84	private:
85	  EmptyBarrier* const empty_barrier_ptr_ = nullptr;
86	
87	  // Consumer signalling Producer of completion
88	  // Ensures all blocks in the Same Row and Column get notifed.
89	  CUTLASS_DEVICE
90	  void consumer_release(uint32_t stage, uint32_t skip = false) {
91	    empty_barrier_ptr_[stage].arrive(0 /*dst_blockid_*/, uint32_t(threadIdx.x % cutlass::NumThreadsPerWarpGroup == 0) & (!skip) /*is_signaling_thread*/);
92	  }
93	
94	};
