952	    CUTLASS_DEVICE void
953	    warp_scheduler_barrier_sync() {
954	        if constexpr (UseSchedulerBarrier) {
955	            cutlass::arch::NamedBarrier::sync(2 * cutlass::NumThreadsPerWarpGroup, static_cast<uint32_t>(FwdNamedBarriers::WarpSchedulerWG1) - 1 + flash::canonical_warp_group_idx_nosync() /*id*/);

280	    using TMA_Qv_ = decltype(make_tma_copy_A_sm90(
281	        GmemTiledCopyQ{},
282	        make_tensor(make_gmem_ptr(static_cast<Element const*>(nullptr)), ShapeQKV{}, StrideQK{}),
283	        SmemLayoutQv{},
284	        TileShape_MNK_QV{},
285	        ClusterShape{}));
286	    using TMA_Qv = std::conditional_t<HasQv, TMA_Qv_, std::nullptr_t>;
